+const MAX_CREDENTIAL_HEADER_BYTES = 16_384;
+const MAX_CREDENTIAL_HEADER_VALUE_BYTES = 8_192;
+const FORBIDDEN_CREDENTIAL_HEADERS = new Set([
+  "connection",
+  "content-length",
+  "host",
+  "proxy-connection",
+  "te",
