import type {
  CallToolResult,
  CreateTaskResult,
  GetPromptResult,
  Implementation,
  Prompt,
  ReadResourceResult,
  Resource,
  ResourceTemplate,
  ServerCapabilities,
  Tool,
  Task,
  ListTasksResult,
} from "@modelcontextprotocol/sdk/types.js";
import {
  McpFnClient,
  type McpFnClientOptions,
  type McpFnClientEvent,
  type McpFnDiagnosticEvent,
  type McpFnTargetDescriptor,
} from "@mcpfn/client";
import {
  createMcpFnScenario,
  type McpFnScenario,
} from "@mcpfn/testing";

const SCENARIO_REDACTION_LIMITS = {
  maxDepth: 8,
  maxArrayEntries: 100,
  maxObjectEntries: 100,
  maxStringLength: 2_048,
} as const;
const SCENARIO_SECRET_MARKER = "${MCPFN_SECRET}";

export interface McpFnInspectorSnapshot {
  formatVersion: 2;
  kind: "mcpfn.inspector-snapshot";
  target: McpFnTargetDescriptor;
  clientState: string;
  server?: Implementation;
  capabilities?: ServerCapabilities;
  tools: Tool[];
  resources: Resource[];
  resourceTemplates: ResourceTemplate[];
  prompts: Prompt[];
  timeline: McpFnInspectorTimelineEvent[];
  droppedEvents: number;
  timelineComplete: boolean;
  droppedInventoryEntries: McpFnInspectorDroppedInventoryEntries;
  inventoryComplete: boolean;
}

export interface McpFnInspectorDroppedInventoryEntries {
  tools: number;
  resources: number;
  resourceTemplates: number;
  prompts: number;
}

export interface McpFnInspectorTimelineEvent {
  formatVersion: 1;
  source: "diagnostic" | "client";
  kind: string;
  at: string;
  event: McpFnDiagnosticEvent | McpFnClientEvent | Record<string, unknown>;
}

export interface McpFnInspectorLimits {
  /** Defaults to 500 events. */
  maxEvents?: number;
  /** Defaults to 512 KiB across the retained timeline. */
  maxTimelineBytes?: number;
  /** Defaults to 500 retained entries for each inventory surface. */
  maxInventoryEntries?: number;
}

export type McpFnInspectorOperation =
  | { kind: "tools.call"; name: string; arguments?: Record<string, unknown> }
  | { kind: "tools.call:task"; name: string; arguments?: Record<string, unknown>; task?: { ttl?: number } }
  | { kind: "resources.read"; uri: string }
  | { kind: "resources.subscribe"; uri: string }
  | { kind: "resources.unsubscribe"; uri: string }
  | { kind: "prompts.get"; name: string; arguments?: Record<string, string> }
  | { kind: "tasks.get"; taskId: string }
  | { kind: "tasks.result"; taskId: string }
  | { kind: "tasks.cancel"; taskId: string }
  | { kind: "tasks.list"; cursor?: string };

export type McpFnInspectorOperationResult =
  | CallToolResult
  | CreateTaskResult
  | ReadResourceResult
  | GetPromptResult
  | Task
  | ListTasksResult
  | void;

export type McpFnExportedScenario = McpFnScenario;

/** Headless inspector; graphical shells and the CLI consume this same engine. */
export class McpFnInspector {
  private readonly events: McpFnInspectorTimelineEvent[] = [];
  private readonly unsubscribes: Array<() => void>;
  private readonly maxEvents: number;
  private readonly maxTimelineBytes: number;
  private readonly maxInventoryEntries: number;
  private timelineBytes = 0;
  private droppedEvents = 0;

  constructor(readonly client: McpFnClient, limits: McpFnInspectorLimits = {}) {
    this.maxEvents = validateLimit(limits.maxEvents ?? 500, "maxEvents");
    this.maxTimelineBytes = validateLimit(
      limits.maxTimelineBytes ?? 524_288,
      "maxTimelineBytes",
    );
    this.maxInventoryEntries = validateLimit(
      limits.maxInventoryEntries ?? 500,
      "maxInventoryEntries",
    );
    this.unsubscribes = [
      client.onDiagnostic((event) => this.record("diagnostic", event.phase, event.at, event)),
      client.onEvent((event) => this.record("client", event.kind, event.at, event)),
    ];
  }

  static create(
    options: McpFnClientOptions & { inspector?: McpFnInspectorLimits },
  ): McpFnInspector {
    const { inspector, ...clientOptions } = options;
    return new McpFnInspector(new McpFnClient(clientOptions), inspector);
  }

  async connect(): Promise<this> {
    await this.client.connect();
    return this;
  }

  async snapshot(): Promise<McpFnInspectorSnapshot> {
    const capabilities = this.client.getServerCapabilities();
    const emptyInventory = { items: [], droppedItems: 0, complete: true };
    const [tools, resources, resourceTemplates, prompts] = await Promise.all([
      capabilities?.tools
        ? this.client.tools.listBounded(this.maxInventoryEntries)
        : Promise.resolve(emptyInventory),
      capabilities?.resources
        ? this.client.resources.listBounded(this.maxInventoryEntries)
        : Promise.resolve(emptyInventory),
      capabilities?.resources
        ? this.client.resources.listTemplatesBounded(this.maxInventoryEntries)
        : Promise.resolve(emptyInventory),
      capabilities?.prompts
        ? this.client.prompts.listBounded(this.maxInventoryEntries)
        : Promise.resolve(emptyInventory),
    ]);
    const droppedInventoryEntries = {
      tools: tools.droppedItems,
      resources: resources.droppedItems,
      resourceTemplates: resourceTemplates.droppedItems,
      prompts: prompts.droppedItems,
    };
    const inventoryComplete = Object.values(droppedInventoryEntries)
      .every((count) => count === 0);
    const redaction = { maxArrayEntries: Math.max(this.maxEvents, this.maxInventoryEntries, 1) };
    const { kind, ...descriptor } = this.client.getTargetDescriptor();
    const server = this.client.getServerVersion();
    // Custom hooks receive payloads only; reconstruct authored discriminators.
    return {
      formatVersion: 2,
      kind: "mcpfn.inspector-snapshot",
      target: { ...this.client.redact(descriptor, redaction), kind },
      clientState: this.client.state,
      server: server === undefined ? undefined : this.client.redact(server, redaction),
      capabilities: capabilities === undefined ? undefined : this.client.redact(capabilities, redaction),
      tools: this.client.redact(tools.items, redaction),
      resources: this.client.redact(resources.items, redaction),
      resourceTemplates: this.client.redact(resourceTemplates.items, redaction),
      prompts: this.client.redact(prompts.items, redaction),
      // Stored events already passed through the client hook; never reapply it.
      timeline: structuredClone(this.events),
      droppedEvents: this.droppedEvents,
      timelineComplete: this.droppedEvents === 0,
      droppedInventoryEntries,
      inventoryComplete,
    };
  }

  async run(operation: McpFnInspectorOperation): Promise<McpFnInspectorOperationResult> {
    if (operation.kind === "tools.call") {
      return this.client.tools.call(operation.name, operation.arguments);
    }
    if (operation.kind === "tools.call:task") {
      return this.client.tools.createTask(operation.name, operation.arguments, operation.task);
    }
    if (operation.kind === "resources.read") {
      return this.client.resources.read(operation.uri);
    }
    if (operation.kind === "resources.subscribe") {
      return this.client.resources.subscribe(operation.uri);
    }
    if (operation.kind === "resources.unsubscribe") {
      return this.client.resources.unsubscribe(operation.uri);
    }
    if (operation.kind === "prompts.get") {
      return this.client.prompts.get(operation.name, operation.arguments);
    }
    if (operation.kind === "tasks.get") return this.client.tasks.get(operation.taskId);
    if (operation.kind === "tasks.result") return this.client.tasks.result(operation.taskId);
    if (operation.kind === "tasks.cancel") return this.client.tasks.cancel(operation.taskId);
    return this.client.tasks.list(operation.cursor);
  }

  exportScenario(
    name: string,
    operation: McpFnInspectorOperation,
    result: McpFnInspectorOperationResult,
  ): McpFnExportedScenario {
    const scenario = createMcpFnScenario(name, operation, result);
    const { formatVersion, kind, sideEffect, ...payload } = scenario;
    const redacted = {
      ...Object.fromEntries(Object.entries(payload).map(([key, value]) => [key, this.client.redact(value, {
        ...SCENARIO_REDACTION_LIMITS,
        // These are user payloads, even when their keys resemble an envelope.
        preserveKeys: false,
        redactionMarker: SCENARIO_SECRET_MARKER,
      })])),
      formatVersion, kind, sideEffect,
    };
    const replaced = redacted as unknown as McpFnExportedScenario;
    const exported = exceedsRedactionBounds(scenario, redacted, SCENARIO_REDACTION_LIMITS)
      ? {
        ...replaced,
        status: "incomplete" as const,
        incompleteReason: "Inspector export exceeded redaction bounds and was truncated",
      }
      : replaced;
    const variables = collectVariables(exported);
    return variables.length ? { ...exported, variables } : exported;
  }

  timeline(): McpFnInspectorTimelineEvent[] {
    return [...this.events];
  }

  private record(
    source: McpFnInspectorTimelineEvent["source"],
    kind: string,
    at: string,
    raw: McpFnDiagnosticEvent | McpFnClientEvent,
  ): void {
    if (this.client.isRedactionOmission(raw)) {
      // The fallback is useful evidence, but the original event is missing.
      this.droppedEvents += 1;
    }
    let event: McpFnInspectorTimelineEvent = {
      formatVersion: 1,
      source,
      kind,
      at,
      event: raw,
    };

item.formatted_output:
    ...artifactOptions,
    scenarios: validateMcpFnScenarios(scenarios),
  };
}

function isScenarioArtifact(value: unknown): value is McpFnScenarioArtifact {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const candidate = value as Record<string, unknown>;
  if (candidate.kind !== "mcpfn.scenarios") return false;
  if (candidate.formatVersion !== 1) {
    throw new Error("Unsupported McpFn scenario artifact formatVersion");
  }
  if (candidate.status !== "complete" && candidate.status !== "incomplete") {
    throw new Error("McpFn scenario artifact status must be complete or incomplete");
  }
  if (candidate.status === "incomplete" && typeof candidate.incompleteReason !== "string") {
    throw new Error("Incomplete McpFn scenario artifact requires incompleteReason");
  }
  return true;
}

export async function runScenarios(
  client: McpFnTestClient<unknown>,
  scenarios: McpFnScenario[],
  options: McpFnScenarioRunOptions = {},
): Promise<McpFnScenarioResult[]> {
  if (
    options.defaultTimeoutMs !== undefined &&
    (
      !Number.isInteger(options.defaultTimeoutMs) ||
      options.defaultTimeoutMs < 1 ||
      options.defaultTimeoutMs > 300_000
    )
  ) {
    throw new Error("defaultTimeoutMs must be an integer from 1 through 300000");
  }
  if (
    options.maxScenarios !== undefined &&
    (!Number.isInteger(options.maxScenarios) || options.maxScenarios < 1)
  ) {
    throw new Error("maxScenarios must be a positive integer");
  }
  if (
    options.maxErrorBytes !== undefined &&
    (!Number.isInteger(options.maxErrorBytes) || options.maxErrorBytes < 64)
  ) {
    throw new Error("maxErrorBytes must be an integer of at least 64");
  }
  if (
    options.maxObservedEvents !== undefined &&
    (!Number.isInteger(options.maxObservedEvents) || options.maxObservedEvents < 1)
  ) {
    throw new Error("maxObservedEvents must be a positive integer");
  }
  if (scenarios.length > (options.maxScenarios ?? 1_000)) {
    throw new Error(`Scenario count exceeds the configured cap of ${options.maxScenarios ?? 1_000}`);
  }
  const results: McpFnScenarioResult[] = [];
  const observedEvents: McpFnClientEvent[] = [];
  const maxObservedEvents = options.maxObservedEvents ?? 500;
  let droppedObservedEvents = 0;
  let attributedDroppedObservedEvents = 0;
  const pushResult = (result: McpFnScenarioResult): void => {
    const newlyDropped = droppedObservedEvents - attributedDroppedObservedEvents;
    results.push({
      ...result,
      ...(newlyDropped > 0
        ? { droppedObservedEvents: (result.droppedObservedEvents ?? 0) + newlyDropped }
        : {}),
    });
    attributedDroppedObservedEvents = droppedObservedEvents;
  };
  const unsubscribe = client.session.onEvent((event) => {
    if (client.session.isRedactionOmission(event)) {
      droppedObservedEvents += 1;
      return;
    }
    observedEvents.push(event);
    if (observedEvents.length > maxObservedEvents) {
      observedEvents.shift();
      droppedObservedEvents += 1;
    }
  });
  let timedOutScenario: string | undefined;
  try {
    for (const scenario of scenarios) {
      const startedAt = performance.now();
      const operation = scenario.kind ?? "tools.call";
      const common = {
        formatVersion: 1 as const,
        name: scenario.name,
        operation,
        ...(isToolScenario(scenario) ? { tool: scenario.tool } : {}),
        sideEffect: scenario.sideEffect ?? defaultSideEffect(operation),
      };
      if (timedOutScenario) {
        pushResult({
          ...common,
          status: "incomplete",
          durationMs: 0,
          error: truncateError(`Skipped after timed-out scenario: ${timedOutScenario}`, options, client),
        });
        continue;
      }
      const resolved = resolveScenarioVariables(scenario, options.variables);
      if (resolved.missing.length > 0) {
        pushResult({
          ...common,
          status: "incomplete",
          durationMs: 0,
          error: truncateError(
            `Missing scenario variables: ${resolved.missing.join(", ")}`,
            options,
            client,
          ),
        });
        continue;
      }
      if (scenario.status === "incomplete") {
        pushResult({
          ...common,
          status: "incomplete",
          durationMs: 0,
          error: truncateError(scenario.incompleteReason ?? "Scenario is incomplete", options, client),
        });
        continue;
      }
      const timeoutMs = scenario.timeoutMs ?? options.defaultTimeoutMs ?? 30_000;
      const controller = new AbortController();
      let timer: ReturnType<typeof setTimeout> | undefined;
      let timedOut = false;
      try {
        await Promise.race([
          executeScenario(client, resolved.scenario, {
            signal: controller.signal,
            timeout: timeoutMs,
          }, observedEvents, options),
          new Promise<never>((_resolve, reject) => {
            timer = setTimeout(() => {
              timedOut = true;
              controller.abort();
              reject(new McpFnAssertionError(`Scenario timed out after ${timeoutMs}ms`));
            }, timeoutMs);
          }),
        ]);
        pushResult({
          ...common,
          status: "passed",
          durationMs: performance.now() - startedAt,
        });
      } catch (error) {
        pushResult({
          ...common,
          status: "failed",
          durationMs: performance.now() - startedAt,
          error: truncateError(error instanceof Error ? error.message : String(error), options, client),
        });
        if (timedOut) timedOutScenario = scenario.name;
      } finally {
        if (timer) clearTimeout(timer);
      }
    }
  } finally {
    const unattributed = droppedObservedEvents - attributedDroppedObservedEvents;
    const lastResult = results.at(-1);
    if (lastResult && unattributed > 0) {
      lastResult.droppedObservedEvents =
        (lastResult.droppedObservedEvents ?? 0) + unattributed;
    }
    unsubscribe();
  }
  return results;
}

export interface McpFnScenarioRunOptions {
  defaultTimeoutMs?: number;
  maxScenarios?: number;
  maxErrorBytes?: number;
  /** Observed client-event count cap. Defaults to 500. */
  maxObservedEvents?: number;
  variables?: Record<string, string | undefined>;
  auth?(scenario: McpFnAuthScenario, signal: AbortSignal): Promise<{
    outcome: "allowed" | "denied";
    code?: string;
  }>;
}

function resolveScenarioVariables(
  scenario: McpFnScenario,
  supplied: Record<string, string | undefined> | undefined,
): { scenario: McpFnScenario; missing: string[] } {
  const values = { ...process.env, ...supplied };
  const required = new Set(scenario.variables ?? []);
  const marker = /\$\{([A-Z][A-Z0-9_]*)\}/g;
  const encodedMarker = /%24%7[Bb]([A-Z][A-Z0-9_]*)%7[Dd]/g;
  const visitString = (value: string): string => {
    for (const match of value.matchAll(marker)) required.add(match[1]);
    for (const match of value.matchAll(encodedMarker)) required.add(match[1]);
    return value
      .replace(marker, (original, name: string) => values[name] ?? original)
      .replace(encodedMarker, (original, name: string) =>
        values[name] === undefined ? original : encodeURIComponent(values[name]),
      );
  };
  const visit = (value: unknown): unknown => {
    if (typeof value === "string") return visitString(value);
    if (Array.isArray(value)) return value.map(visit);
    if (value && typeof value === "object") {
      return Object.fromEntries(
        Object.entries(value as Record<string, unknown>).map(([key, entry]) => [
          visitString(key),
          visit(entry),
        ]),
      );
    }
    return value;
  };
  const resolved = visit(scenario) as McpFnScenario;
  return {
    scenario: resolved,
    missing: [...required]
      .filter((name) => values[name] === undefined)
      .sort(compareCodeUnits),
  };
}

export function createMcpFnScenarioReport(
  results: McpFnScenarioResult[],
  options: { manifestHash?: string; maxBytes?: number } = {},
): McpFnScenarioReport {
  const failed = results.filter((result) => result.status === "failed").length;
  const incomplete = results.filter((result) => result.status === "incomplete").length;
  const droppedObservedEvents = results.reduce(
    (total, result) => total + (result.droppedObservedEvents ?? 0),
    0,
  );
  const report: McpFnScenarioReport = {
    formatVersion: 1,
    kind: "mcpfn.scenario-report",
    status: incomplete === 0 && droppedObservedEvents === 0 ? "complete" : "incomplete",
    ...(options.manifestHash ? { manifestHash: options.manifestHash } : {}),
    total: results.length,
    passed: results.length - failed - incomplete,
    failed,
    incomplete,
    droppedResults: 0,
    droppedObservedEvents,
    ...(droppedObservedEvents > 0
      ? { incompleteReason: "Observed client events exceeded maxObservedEvents" }
      : {}),
    results: structuredClone(results),
  };
  const maxBytes = options.maxBytes ?? 1_048_576;
  if (!Number.isInteger(maxBytes) || maxBytes < 1_024) {
    throw new Error("maxBytes must be an integer of at least 1024");
  }
  if (serializedBytes(report) > maxBytes) {
    report.status = "incomplete";
    report.incompleteReason = "Report content exceeded maxBytes and was truncated";
  }
  while (serializedBytes(report) > maxBytes && report.results.length > 0) {
          } else {
            timeline.push(safeEvent);
            timelineSizes.push(bytes);
            timelineBytes += bytes;
            while (timeline.length > maxTimelineEvents || timelineBytes > maxReportBytes) {
              timelineCountExceeded ||= timeline.length > maxTimelineEvents;
              timelineBytesExceeded ||= timelineBytes > maxReportBytes;
              timeline.shift();
              timelineBytes -= timelineSizes.shift()!;
              droppedTimelineEvents += 1;
            }
          }
          await consumerDiagnostic?.(safeEvent);
        },
      },
    );
    await client.session.connect();
    if (options.manifest) {
      manifestChecked = true;
      await assertManifestContract(client, options.manifest, {
        expectedToolNames: options.expectedToolNames,
      });
    }
    if (!options.manifest && options.expectedToolNames) {
      const actual = (await client.listTools()).map((tool) => tool.name).sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
      const expected = [...options.expectedToolNames].sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
      if (stableJson(actual) !== stableJson(expected)) {
        throw new McpFnAssertionError(`Tool inventory mismatch: expected ${stableJson(expected)}, actual ${stableJson(actual)}`);
      }
    }
    execution = {
      results: await runScenarios(
        client,
        options.scenarios ?? [],
        options.scenarioRun,
      ),
      server: client.session.getServerVersion(),
      capabilities: client.session.getServerCapabilities(),
    };
  } catch (error) {
    try {
      failure = normalizeMcpFnReportFailure(redactSuiteArtifact(options.target, error, { preserveKeys: true }));
    } catch {
      // Arbitrary error properties/proxies can throw, including secret-bearing errors.
      failure = normalizeMcpFnReportFailure({ name: "RedactionError", code: "MCPFN_REDACTION_FAILED", message: "Target failure omitted because credential redaction failed" });
    }
  } finally {
    try {
      // Custom hooks may depend on credentials cleared by close. Capture every
      // target-controlled report value while the session still owns that state.
      if (client?.session.state === "connected") {
        const { kind, ...descriptor } = options.target.describe();
        capturedTarget = { ...redactSuiteArtifact(options.target, descriptor), kind };
        capturedManifestHash = options.manifest ? redactSuiteArtifact(options.target, options.manifest.hash) : undefined;
        execution = {
          server: execution.server === undefined ? undefined : redactSuiteArtifact(options.target, execution.server),
          capabilities: execution.capabilities === undefined ? undefined : redactSuiteArtifact(options.target, execution.capabilities),
          results: execution.results.map(result => ({
            ...result,
            name: redactSuiteArtifact(options.target, result.name),
            operation: redactSuiteArtifact(options.target, result.operation),
            ...(result.tool === undefined ? {} : { tool: redactSuiteArtifact(options.target, result.tool) }),
          })),
        };
      } else if (execution.results.length || execution.server || execution.capabilities) {
        projectionFailed = true;
      }
    } catch { projectionFailed = true; }
    try {
      await client?.close();
    } catch (error) {
      const owner = client;
      if (owner) retainedCleanup = () => owner.close();
      cleanupFailure = normalizeMcpFnReportFailure({ name: "CleanupError", message: "Target cleanup failed", code: "MCPFN_TARGET_CLEANUP_FAILED", phase: "transport-close" });
      if (!failure) failure = cleanupFailure;
    }
  }
  failure ??= cleanupFailure;
  const results = execution.results;
  const failed = results.filter((result) => result.status === "failed").length;
  const incomplete = results.filter((result) => result.status === "incomplete").length;
  const droppedObservedEvents = results.reduce(
    (total, result) => total + (result.droppedObservedEvents ?? 0),
    0,
  );
  const artifactIncomplete = Boolean(failure) || incomplete > 0 ||
    droppedTimelineEvents > 0 ||
    droppedObservedEvents > 0;
  const report: McpFnTargetSuiteReport = {
    formatVersion: 1,
    kind: "mcpfn.target-suite-report",
    status: artifactIncomplete ? "incomplete" : "complete",
    runtime: {
      node: process.version,
      scenarioFormatVersion: 1,
      reportSchemaVersion: MCPFN_REPORT_SCHEMA_VERSION,
      packages: { testing: MCPFN_TESTING_VERSION },
    },
    ok: failed === 0 && !artifactIncomplete,
    target: capturedTarget,
    server: execution.server,
    capabilities: execution.capabilities,
    manifestChecked,
    ...(capturedManifestHash === undefined ? {} : { manifestHash: capturedManifestHash }),
    total: results.length,
    passed: results.length - failed - incomplete,
    failed,
    incomplete,
    droppedResults: 0,
    droppedObservedEvents,
    ...(failure || droppedTimelineEvents > 0 || droppedObservedEvents > 0
      ? {
        incompleteReason: [
          ...(failure ? [`${failure.layer}: ${failure.message}`] : []),
          ...(cleanupFailure ? [`Cleanup: ${cleanupFailure.message}`] : []),
          ...(timelineSerializationFailed ? ["Diagnostic timeline contained non-JSON data"] : []),
          ...(timelineRedactionFailed ? ["Diagnostic timeline redaction failed; original events omitted"] : []),
          ...(timelineCountExceeded ? ["Diagnostic timeline exceeded maxTimelineEvents"] : []),
          ...(timelineBytesExceeded ? ["Diagnostic timeline exceeded maxReportBytes"] : []),
          ...(droppedObservedEvents > 0
            ? ["Observed client events exceeded maxObservedEvents"]
            : []),
        ].join("; "),
      }
      : {}),
    ...(failure ? { failure } : {}),
    timeline,
    droppedTimelineEvents,
    results,
  };
  let finalized: McpFnTargetSuiteReport;
  try {
    if (projectionFailed) throw new Error("Report payload redaction failed");
    // Custom redaction already completed before cleanup. Built-in report scopes
    // remain active here for bounded final serialization.
    finalized = enforceReportCap(redactTargetCredentials(options.target, report, { preserveKeys: true }), maxReportBytes);
  } catch (error) {
    finalized = enforceReportCap({ ...report, ok: false, status: "incomplete",
      incompleteReason: error instanceof McpFnRedactionLimitError
        ? "Credential redaction exceeded its traversal budget"
        : "Report content omitted because safe serialization failed",
  const report = await runMcpFnTargetSuite({ target });
  expect(close).toHaveBeenCalledOnce();
  expect(report).toMatchObject({ ok: false, status: "incomplete", target: { kind: "custom" }, results: [], timeline: [] });
  expect(report.incompleteReason).toContain("safe serialization failed");
  expect(JSON.stringify(report)).not.toContain(secret);
});


