describe("McpFn testing", () => {
  it("counts redaction-fallback client events as omitted evidence", async () => {
    const client = McpFnTestClient.createTarget(customTarget({
      kind: "custom",
      open: async () => { throw new Error("unused"); },
      redact: <T>(value: T): T => {
        if (value && typeof value === "object" && "secret" in value) {
          throw new Error("event redaction unavailable");
        }
        return value;
      },
    }));
    const emitEvent = (client.session as unknown as {
      emitEvent(kind: "logging.message", payload: unknown): Promise<void>;
    }).emitEvent.bind(client.session);
    const results = await runScenarios(client, [
      {
        name: "emit fallback",
        kind: "auth.assert",
        phase: "emit-event",
        expect: { outcome: "allowed" },
      },
      {
        name: "do not match omitted event",
        kind: "events.expect",
        event: "logging.message",
      },
    ], {
      auth: async () => {
        await emitEvent("logging.message", { secret: true });
        return { outcome: "allowed" };
      },
    });
    expect(results[0]).toMatchObject({ status: "passed", droppedObservedEvents: 1 });
    expect(results[1]).toMatchObject({ status: "failed" });
  });

  it("substitutes declared variables in scenario property keys", async () => {
    const resolvedKey = "resolved-key";
    const server = createMcpFnServer({
      info: { name: "variable-keys", version: "1.0.0" },
      registry: new McpFnRegistry().register({
        name: "echo-key",
        description: "Echo a variable-keyed input.",
        inputSchema: {
      emitNotifications.mockImplementation((listener) => {
        observeEvent = listener;
        return () => undefined;
      });
      const eventBounded = await runScenarios(client, [{
        name: "bounded observed events",
        kind: "auth.assert",
        phase: "emit-events",
        expect: { outcome: "allowed" },
      }], {
        maxObservedEvents: 2,
        auth: async () => {
          for (let index = 0; index < 5; index += 1) {
            observeEvent?.({ kind: "logging.message", payload: { index } });
          }
          return { outcome: "allowed" };
        },
      });
      const eventBoundedReport = createMcpFnScenarioReport(eventBounded);
      expect(eventBounded).toMatchObject([{ status: "passed", droppedObservedEvents: 3 }]);
      expect(eventBoundedReport).toMatchObject({
        status: "incomplete",
        droppedObservedEvents: 3,
        incompleteReason: "Observed client events exceeded maxObservedEvents",
      });
      emitNotifications.mockRestore();
    } finally {
      await client.close();
    }
  });

  it("attributes observed-event loss while later scenarios are skipped", async () => {
    const client = await McpFnTestClient.connect(createMcpFnServer({
      info: { name: "event-loss-after-timeout", version: "1.0.0" },
      registry: new McpFnRegistry(),
    }));
    const onEvent = vi.spyOn(client.session, "onEvent");
    let observeEvent: ((event: Parameters<Parameters<typeof client.session.onEvent>[0]>[0]) => void) |
      undefined;
    onEvent.mockImplementation((listener) => {
      observeEvent = listener;
      return () => undefined;
    });
    const skippedScenario = {
      get name() {
        for (let index = 0; index < 5; index += 1) {
          observeEvent?.({ kind: "logging.message", payload: { index } });
        }
        return "skipped while events continue";
      },
      kind: "auth.assert" as const,
      phase: "must-not-run",
      expect: { outcome: "allowed" as const },
    };
    try {
      const results = await runScenarios(client, [
        {
          name: "times out",
          kind: "auth.assert",
          phase: "never-settles",
          timeoutMs: 5,
          expect: { outcome: "allowed" },
        },
        skippedScenario,
      ], {
        maxObservedEvents: 2,
        auth: async () => new Promise(() => undefined),
      });

      expect(results).toMatchObject([
        { status: "failed" },
        { status: "incomplete", droppedObservedEvents: 3 },
      ]);
      expect(createMcpFnScenarioReport(results)).toMatchObject({
        status: "incomplete",
        droppedObservedEvents: 3,
        incompleteReason: "Observed client events exceeded maxObservedEvents",
      });
    } finally {
      onEvent.mockRestore();
      await client.close();
    }
  });

  it("preserves the complete server implementation identity", async () => {
    const server = createMcpFnServer({
        },
      }),
