function scrubCredentials<T>(value: T, values: Iterable<string>, preserveKeys = false, redactionMarker?: string): T {
  // Preserve whether a pattern came from opaque text or a serializer. Literal
  // percent sequences in credentials must not acquire URL hex-case semantics.
  const variants = [...values].filter(Boolean).flatMap(secret => [
    { value: secret, encoded: false },
    { value: JSON.stringify(secret).slice(1, -1), encoded: false },
    { value: encodeURIComponent(secret), encoded: true },
    { value: new URLSearchParams({ value: secret }).toString().slice("value=".length), encoded: true },
  ]).sort((a, b) => b.value.length - a.value.length);
  let entries = 0, stringBytes = 0;
  const budget = (input: REDACTED, depth = 0): void => {
    input = specialValue(input);
    if ((Array.isArray(input) && input.length > 100_000) || ++entries > 100_000 || depth > 32) throw new McpFnRedactionLimitError();
    if (typeof input === "string") {
      stringBytes += Buffer.byteLength(input);
      if (input.length > 262_144 || stringBytes > 2_097_152) throw new McpFnRedactionLimitError();
    } else if (input && typeof input === "object") {
      for (const key in input) if (Object.hasOwn(input, key)) {
        budget(key, depth + 1);
        budget((input as Record<string, REDACTED>)[key], depth + 1);
      }
    }
  };
  // Check before either redactor allocates copies. Exceeding a budget is an
  // explicit failure, never silent truncation of a typed report collection.
  budget(value);
  const patterns = variants.map(({ value, encoded }) => {
    const literal = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    // Only generated percent escapes accept mixed-case hex digits.
    return encoded
      ? literal.replace(/%[0-9A-Fa-f]{2}/g, escape => escape.replace(/[A-Fa-f]/g, hex => `[${hex.toLowerCase()}${hex.toUpperCase()}]`))
      : literal;
  });
  const secretPattern = patterns.length ? new RegExp(patterns.join("|"), "g") : undefined;
  const replacementPattern = patterns.length ? new RegExp(patterns.join("|")) : undefined;
  const structuralMatchers = patterns.map((pattern) => ({
    pattern,
    expression: new RegExp(pattern),
  }));
  const structuralPatterns = new Set<string>();
  const preserveStructural = (input: string): string => {
    if (!replacementPattern?.test(input)) return input;
    for (const { pattern, expression } of structuralMatchers) {
      if (expression.test(input)) structuralPatterns.add(pattern);
    }
    return input;
  };
  // A requested marker is itself output and must not reproduce a credential.
  if (secretPattern) {
    const markerContainsSecret = secretPattern.test(redactionMarker ?? "[REDACTED]");
    secretPattern.lastIndex = 0;
    if (markerContainsSecret) redactionMarker = "";
  }
  const clientKinds = new Set(["logging.message", "progress", "tasks.status", "resources.updated", "tools.list_changed", "resources.list_changed", "prompts.list_changed", "resources.subscribed", "resources.unsubscribed", "client.roots", "client.sampling", "client.elicitation"]);
  const scrub = (input: REDACTED, role = "payload", field = "", finalPass = false): REDACTED => {
    input = specialValue(input);
    if (typeof input === "string") {
      if ((role === "root" || role === "inspectorEvent") && field === "kind" && clientKinds.has(input)) return preserveStructural(input);
      if (role === "root" && field === "clientState" && ["idle", "connecting", "authorization-required", "connected", "closing", "closed"].includes(input)) return preserveStructural(input);
      if (role === "target" && field === "kind" && ["authenticated-streamable-http", "streamable-http", "stdio", "in-memory", "custom"].includes(input)) return preserveStructural(input);
      if ((role === "packages" && field === "testing") || (role === "runtime" && ["node", "reportSchemaVersion"].includes(field)) || (role === "root" && field === "suiteVersion")) return preserveStructural(input);
      if ((role === "root" || role === "result") && field === "status" && ["passed", "failed", "incomplete", "complete"].includes(input)) return preserveStructural(input);
      if ((role === "root" || role === "diagnostic") && field === "outcome" && ["started", "succeeded", "failed"].includes(input)) return preserveStructural(input);
      if (role === "root" && field === "kind" && ["mcpfn.target-suite-report", "mcpfn.inspector-snapshot", "mcpfn.official-conformance-report"].includes(input)) return preserveStructural(input);
      if ((role === "root" || role === "diagnostic" || role === "failure") && field === "phase" && ["resource-discovery", "authorization-server-discovery", "client-registration", "authorization-request", "authorization-callback", "token-exchange", "token-refresh", "token-revocation", "transport-connect", "mcp-initialize", "capability-operation", "transport-close"].includes(input)) return preserveStructural(input);
      if (role === "failure" && field === "layer" && ["mcpfn-preflight", "authorization-server", "resource-server", "mcp-initialization", "scenario", "upstream-conformance"].includes(input)) return preserveStructural(input);
      if (role === "inspectorEvent" && field === "source" && ["diagnostic", "client"].includes(input)) return preserveStructural(input);
      if (role === "result" && field === "sideEffect" && ["none", "idempotent", "non-idempotent"].includes(input)) return preserveStructural(input);
      // Whole-string rejection cannot compose another credential by joining pieces.
      // Run after both redactors; never feed this result through another redactor.
      if (finalPass) return replacementPattern?.test(input) ? "" : input;
      return secretPattern ? input.replace(secretPattern, secret => {
        const replacement = redactionMarker ?? (secret.length < 10 ? (secret.includes("*") ? "#" : "*").repeat(secret.length) : "[REDACTED]");
        // Every generated mask must be safe against the entire credential set.
        return replacementPattern!.test(replacement) ? "" : replacement;
      }) : input;
    }
    if (Array.isArray(input)) {
      const result = input.map(entry => scrub(entry, role, "", finalPass));
      assertPayloadSerialization(result, role, finalPass, replacementPattern);
      return result;
    }
    if (input && typeof input === "object") {
      const result = Object.fromEntries(Object.entries(input).map(([key, entry]) => {
        const fixed = envelopeKeys[role]?.has(key) ?? false;
        if (fixed) preserveStructural(key);
        let childRole = "payload";
        if (fixed) {
          if (key === "results") childRole = "result";
          else if (key === "timeline") childRole = (value as any)?.kind === "mcpfn.inspector-snapshot" ? "inspectorEvent" : "diagnostic";
          else if (["failure", "runtime", "packages", "droppedInventoryEntries", "target"].includes(key)) childRole = key;
          else if (role === "inspectorEvent" && key === "event") childRole = (input as { source?: string }).source === "client" ? "root" : "diagnostic";
        }
        return [fixed ? key : scrub(key, "payload", "", finalPass), typeof entry === "string" ? scrub(entry, fixed ? role : "payload", key, finalPass) : scrub(entry, childRole, "", finalPass)];
      }));
      assertPayloadSerialization(result, role, finalPass, replacementPattern);
      return result;
    }
    return input;
  };
  const timelineEvent = value && typeof value === "object" && ["client", "diagnostic"].includes((value as { source?: string }).source ?? "");
  const role = preserveKeys ? (timelineEvent ? "inspectorEvent" : "root") : "payload";
  const scrubbed = scrub(value, role);
  const generic = redactOAuthValue(scrubbed, { maxStringLength: 262_144, maxDepth: 64, maxArrayEntries: 100_000, maxObjectEntries: 100_000, ...(redactionMarker !== undefined ? { redactionMarker } : {}) });
  const result = scrub(generic, role, "", true) as T;
  const boundaryPatterns = patterns.filter((pattern) => !structuralPatterns.has(pattern));
  assertPayloadSerialization(
    result,
    "payload",
    true,
    boundaryPatterns.length ? new RegExp(boundaryPatterns.join("|")) : undefined,
  );
  return result;
}

function assertPayloadSerialization(
  value: REDACTED,
  role: string,
  finalPass: boolean,
  credentialPattern: RegExp | undefined,
): void {
  if (!finalPass || role !== "payload" || !credentialPattern) return;
  const serialized = JSON.stringify(value);
  if (serialized !== undefined && credentialPattern.test(serialized)) {
    throw new McpFnRedactionLimitError(
      "Credential redaction could not guarantee safe serialized output",
    );
  }
}

/** Remove known opaque credential values as well as credential-shaped fields. */
export function redactTargetCredentials<T>(target: McpFnTarget, value: T, options: { preserveKeys?: boolean; redactionMarker?: string } = {}): T {
  const state = targetSecrets.get(target);
  return scrubCredentials(value, new Set([...(state?.active.keys() ?? []), ...[...(state?.scopes ?? [])].flatMap((scope) => [...scope])]), options.preserveKeys, options.redactionMarker);
}

/** Redact authenticated conformance output using the acquired credential. */
export function redactRemoteCredential<T>(credential: McpFnRemoteCredential, value: T, options: { preserveKeys?: boolean } = {}): T {
  return scrubCredentials(value, credentialValues(credential.headers), options.preserveKeys);
}
function readRedactedCollection(
  value: REDACTED,
  key: "entries" | "values",
): REDACTED[] {
  if (!value || typeof value !== "object") return [];
  const collection = (value as Record<string, REDACTED>)[key];
  return Array.isArray(collection) ? collection : [];
}

function collectVariables(value: REDACTED): string[] {
  const variables = new Set<string>();
  const visit = (entry: REDACTED): void => {
    if (typeof entry === "string") {
      for (const match of entry.matchAll(
        /\$\{([A-Z][A-Z0-9_]*)\}|%24%7[Bb]([A-Z][A-Z0-9_]*)%7[Dd]/g,
      )) {
        variables.add(match[1] ?? match[2]);
      }
    } else if (Array.isArray(entry)) {
      entry.forEach(visit);
    } else if (entry && typeof entry === "object") {
      for (const [key, value] of Object.entries(entry as Record<string, REDACTED>)) {
        visit(key);
        visit(value);
      }
    }
  };
  visit(value);
  return [...variables].sort(compareCodeUnits);
}

function compareCodeUnits(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
